srcDoc.css:
* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: #eef1f5;
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  color: #111827;
}

.page {
  min-height: 100vh;
  display: grid;
  place-items: start center;
  padding: 24px;
}

.print-button {
  position: sticky;
  top: 12px;
  z-index: 10;
  border: 0;
  background: #111827;
  color: white;
  border-radius: 6px;
  min-height: 38px;
  padding: 0 18px;
  font-weight: 800;
  margin-bottom: 12px;
  cursor: pointer;
}

.receipt {
  width: 380px;
  background: white;
  padding: 20px;
  border: 1px solid #d9dee8;
  box-shadow: 0 18px 60px rgba(15, 23, 42, 0.14);
}

.company {
  text-align: center;
}

.logo {
  max-width: 120px;
  max-height: 56px;
  object-fit: contain;
  margin-bottom: 8px;
}

.company h1 {
  margin: 0 0 8px;
  font-size: 20px;
  letter-spacing: 0;
}

.muted,
.company .muted {
  color: #5f6b7a;
  font-size: 12px;
  line-height: 1.45;
}

.divider {
  border-top: 1px dashed #111827;
  margin: 14px 0;
}

.title-block {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.title-block span,
.info-grid label,
.customer label,
.fiscal label {
  display: block;
  font-size: 10px;
  color: #687386;
  text-transform: uppercase;
  font-weight: 900;
}

.title-block strong {
  display: block;
  font-size: 15px;
  margin-top: 3px;
}

.title-block small {
  display: block;
  color: #697386;
  margin-top: 2px;
}

.title-block b {
  align-self: start;
  background: #eef4ff;
  color: #1746a2;
  border-radius: 999px;
  padding: 5px 9px;
  font-size: 11px;
}

.info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
}

.info-grid span,
.fiscal span {
  display: block;
  font-size: 12px;
  font-weight: 700;
  margin-top: 2px;
  word-break: break-word;
}

.customer {
  border: 1px solid #e1e7ef;
  border-radius: 6px;
  padding: 10px;
}

.customer strong {
  display: block;
  margin-top: 3px;
  font-size: 13px;
}

.customer span {
  display: block;
  margin-top: 3px;
  color: #5d6878;
  font-size: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  font-size: 11px;
  color: #4b5563;
  text-align: left;
  border-bottom: 1px solid #d9dee8;
  padding: 0 0 7px;
}

td {
  padding: 8px 0;
  border-bottom: 1px solid #eef1f5;
  vertical-align: top;
  font-size: 12px;
}

td strong {
  display: block;
}

td small {
  display: block;
  color: #6b7280;
  margin-top: 2px;
}

.num {
  text-align: right;
  white-space: nowrap;
}

.totals {
  display: grid;
  gap: 7px;
}

.totals div,
.payment-lines div {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
}

.totals span,
.payment-lines span {
  color: #596579;
}

.totals strong,
.payment-lines strong {
  text-align: right;
}

.totals .grand {
  border-top: 1px solid #111827;
  padding-top: 8px;
  margin-top: 4px;
  font-size: 15px;
}

.payment-lines h2 {
  margin: 0 0 8px;
  font-size: 13px;
}

.fiscal {
  display: grid;
  gap: 7px;
}

.qr-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  text-align: center;
}

.qr-grid img {
  width: 96px;
  height: 96px;
  max-width: 100%;
}

.qr-grid span,
.barcode span,
footer span {
  display: block;
  color: #5f6b7a;
  font-size: 10px;
  font-weight: 700;
}

.barcode {
  text-align: center;
  margin-top: 14px;
}

.barcode svg {
  max-width: 100%;
}

footer {
  text-align: center;
  margin-top: 16px;
  display: grid;
  gap: 4px;
}

footer strong {
  font-size: 13px;
}

.empty {
  min-height: 260px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 8px;
  color: #5f6b7a;
}

.empty strong {
  font-size: 18px;
  color: #111827;
}

@media print {
  body {
    background: white;
  }
  .no-print {
    display: none !important;
  }
  .page {
    display: block;
    padding: 0;
  }
  .receipt {
    width: 80mm;
    border: 0;
    box-shadow: none;
    padding: 4mm;
  }
}

