import React from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";
import QRCode from "https://esm.sh/qrcode@1.5.3";
import JsBarcode from "https://esm.sh/jsbarcode@3.11.6";

function money(value) {
  return Number(value || 0).toFixed(2);
}

function qty(value) {
  return Number(value || 0).toFixed(3);
}

function text(value, fallback = "") {
  if (value === null || value === undefined) return fallback;
  if (typeof value === "object") return fallback;
  return String(value);
}

function formatDate(value) {
  if (!value) return "";
  return new Date(value).toLocaleDateString("en-GB");
}

function formatDateTime(value) {
  if (!value) return "";
  return new Date(value).toLocaleString("en-GB");
}

function fiscalPayload(header) {
  if (header.fiscalVerificationUrl) return header.fiscalVerificationUrl;

  return [
    "FISCAL_RECEIPT",
    `FISCAL_NO=${header.fiscalNumber || header.documentNumber || ""}`,
    `INTERNAL_NO=${header.documentNumber || ""}`,
    `DATE=${header.documentDate || ""}`,
    `TOTAL=${header.totalAmount || ""}`,
    `CURRENCY=${header.currencyCode || "EUR"}`,
    `ZKI=${header.zki || ""}`,
    `JIR=${header.jir || ""}`
  ].join("|");
}

function receiptPayload(header) {
  return [
    "AXON_POS_RECEIPT",
    `DOCUMENT_ID=${header.documentId || ""}`,
    `DOCUMENT_NO=${header.documentNumber || ""}`,
    `FISCAL_NO=${header.fiscalNumber || ""}`,
    `DATE=${header.documentDate || ""}`,
    `TOTAL=${header.totalAmount || ""}`,
    `CURRENCY=${header.currencyCode || "EUR"}`
  ].join("|");
}

function returnPayload(header) {
  return [
    "POS_RETURN",
    `DOCUMENT_ID=${header.documentId || ""}`,
    `FISCAL_NO=${header.fiscalNumber || ""}`,
    `DOCUMENT_NO=${header.documentNumber || ""}`,
    `DATE=${header.documentDate || ""}`,
    `WAREHOUSE=${header.warehouseName || ""}`,
    `TOTAL=${header.totalAmount || ""}`,
    `CURRENCY=${header.currencyCode || "EUR"}`
  ].join("|");
}

function barcodeValue(header) {
  return text(
    header.fiscalNumber ||
    header.documentNumber ||
    header.documentId ||
    ""
  ).replace(/[^A-Za-z0-9-]/g, "");
}

function App() {
  const data = appsmith.model || {};
  const header = data.header || {};
  const items = data.items || [];
  const taxes = data.taxes || [];
  const payments = data.payments || [];

  const [fiscalQr, setFiscalQr] = React.useState("");
  const [receiptQr, setReceiptQr] = React.useState("");
  const [returnQr, setReturnQr] = React.useState("");

  const barcodeRef = React.useRef(null);

  const documentKey = `${header.documentNumber || ""}-${header.fiscalNumber || ""}-${header.jir || ""}`;

  React.useEffect(() => {
    async function buildCodes() {
      if (!header.documentNumber) return;

      setFiscalQr(await QRCode.toDataURL(fiscalPayload(header), {
        margin: 1,
        width: 148,
        errorCorrectionLevel: "M"
      }));

      setReceiptQr(await QRCode.toDataURL(receiptPayload(header), {
        margin: 1,
        width: 148,
        errorCorrectionLevel: "M"
      }));

      setReturnQr(await QRCode.toDataURL(returnPayload(header), {
        margin: 1,
        width: 148,
        errorCorrectionLevel: "M"
      }));
    }

    buildCodes();
  }, [documentKey]);

  React.useEffect(() => {
    const value = barcodeValue(header);

    if (!value || !barcodeRef.current) return;

    JsBarcode(barcodeRef.current, value, {
      format: "CODE128",
      displayValue: true,
      fontSize: 12,
      height: 50,
      margin: 0
    });
  }, [documentKey]);

  const printReceipt = () => window.print();

  if (!header.documentNumber) {
    return (
      <div className="empty">
        <strong>No receipt selected</strong>
        <span>Select a POS receipt and press Print.</span>
      </div>
    );
  }

  return (
    <div className="page">
      <button className="print-button no-print" onClick={printReceipt}>
        Print
      </button>

      <div className="receipt">
        <section className="company">
          {(header.companyLogoPath || header.company_logo_path) && (
            <img className="logo" src={header.companyLogoPath || header.company_logo_path} />
          )}

          <h1>{text(header.companyName, "Company")}</h1>

          <div className="muted">
            {header.companyAddress && <div>{header.companyAddress}</div>}
            {(header.companyPostalCode || header.companyCity) && (
              <div>{header.companyPostalCode} {header.companyCity}</div>
            )}
            {header.companyTaxNumber && <div>Tax No: {header.companyTaxNumber}</div>}
            {header.companyRegistrationNumber && <div>Reg No: {header.companyRegistrationNumber}</div>}
            {header.companyEmail && <div>{header.companyEmail}</div>}
            {header.companyPhone && <div>{header.companyPhone}</div>}
          </div>
        </section>

        <div className="divider" />

        <section className="title-block">
          <div>
            <span>Fiscal Receipt</span>
            <strong>{text(header.fiscalNumber || header.documentNumber)}</strong>
            <small>Internal No: {text(header.documentNumber)}</small>
          </div>
          <b>{text(header.status, "POSTED")}</b>
        </section>

        <div className="divider" />

        <section className="info-grid">
          <div><label>Date</label><span>{formatDate(header.documentDate)}</span></div>
          <div><label>Issued</label><span>{formatDateTime(header.createdAt)}</span></div>
          <div><label>Warehouse</label><span>{text(header.warehouseName, "-")}</span></div>
          <div><label>Cashier</label><span>{text(header.cashier || header.createdBy || data.username, "-")}</span></div>
          <div><label>Payment</label><span>{text(header.paymentMethod, "-")}</span></div>
          <div><label>Currency</label><span>{text(header.currencyCode, "EUR")}</span></div>
        </section>

        {(header.partnerName || header.customerName || header.partnerTaxNumber) && (
          <>
            <div className="divider" />
            <section className="customer">
              <label>Customer</label>
              <strong>{text(header.partnerName || header.customerName)}</strong>
              {header.partnerTaxNumber && <span>Tax No: {header.partnerTaxNumber}</span>}
            </section>
          </>
        )}

        <div className="divider" />

        <table>
          <thead>
            <tr>
              <th>Item</th>
              <th className="num">Qty</th>
              <th className="num">Price</th>
              <th className="num">Total</th>
            </tr>
          </thead>
          <tbody>
            {items.map((item, index) => (
              <tr key={index}>
                <td>
                  <strong>{text(item.description || item.productName || item.productCode, "Item")}</strong>
                  {(item.productCode || item.barcode) && (
                    <small>{text(item.productCode)} {item.barcode ? `/ ${item.barcode}` : ""}</small>
                  )}
                </td>
                <td className="num">{qty(item.quantity)}</td>
                <td className="num">{money(item.unitPrice)}</td>
                <td className="num">{money(item.lineTotal)}</td>
              </tr>
            ))}
          </tbody>
        </table>

        <div className="divider" />

        <section className="totals">
          <div><span>Subtotal</span><strong>{money(header.subtotalAmount)} {text(header.currencyCode, "EUR")}</strong></div>
          <div><span>Discount</span><strong>{money(header.discountAmount)} {text(header.currencyCode, "EUR")}</strong></div>
          <div><span>Tax</span><strong>{money(header.taxAmount)} {text(header.currencyCode, "EUR")}</strong></div>
          <div className="grand"><span>Total</span><strong>{money(header.totalAmount)} {text(header.currencyCode, "EUR")}</strong></div>
          <div><span>Paid</span><strong>{money(header.paidAmount || header.totalAmount)} {text(header.currencyCode, "EUR")}</strong></div>
        </section>

        {payments.length > 0 && (
          <>
            <div className="divider" />
            <section className="payment-lines">
              <h2>Payments</h2>
              {payments.map((payment, index) => (
                <div key={index}>
                  <span>{text(payment.paymentMethod, "PAYMENT")} {payment.cardType ? `· ${payment.cardType}` : ""}</span>
                  <strong>{money(payment.amount)} {text(header.currencyCode, "EUR")}</strong>
                </div>
              ))}
            </section>
          </>
        )}

        {taxes.length > 0 && (
          <>
            <div className="divider" />
            <table>
              <thead>
                <tr>
                  <th>Tax %</th>
                  <th className="num">Base</th>
                  <th className="num">Tax</th>
                </tr>
              </thead>
              <tbody>
                {taxes.map((tax, index) => (
                  <tr key={index}>
                    <td>{money(tax.taxRate)}%</td>
                    <td className="num">{money(tax.taxableAmount)}</td>
                    <td className="num">{money(tax.taxAmount)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </>
        )}

        <div className="divider" />

        <section className="fiscal">
          <div><label>Fiscal No</label><span>{text(header.fiscalNumber, "-")}</span></div>
          <div><label>ZKI</label><span>{text(header.zki, "-")}</span></div>
          <div><label>JIR</label><span>{text(header.jir, "-")}</span></div>
        </section>

        <div className="divider" />

        <section className="qr-grid">
          <div>{fiscalQr && <img src={fiscalQr} />}<span>Fiscal verification</span></div>
          <div>{receiptQr && <img src={receiptQr} />}<span>Receipt reference</span></div>
          <div>{returnQr && <img src={returnQr} />}<span>Return lookup</span></div>
        </section>

        <section className="barcode">
          <svg ref={barcodeRef}></svg>
          <span>Receipt barcode</span>
        </section>

        <footer>
          <strong>Thank you for your purchase!</strong>
          <span>Please keep this receipt as proof of purchase.</span>
        </footer>
      </div>
    </div>
  );
}

function render() {
  ReactDOM.render(<App />, document.getElementById("root"));
}

appsmith.onReady(() => {
  render();
  appsmith.onModelChange(render);
});
